/** [SbListRow] with formatted [title], [meta] and [text] (§14.4): struck text, a marked file name (sbFileName). */
@Composable
fun SbListRow(
    title: AnnotatedString,
    modifier: Modifier = Modifier,
    meta: AnnotatedString? = null,
    text: AnnotatedString? = null,
    lead: (@Composable () -> Unit)? = null,
    trail: (@Composable RowScope.() -> Unit)? = null,
    onClick: (() -> Unit)? = null,
    hairline: Boolean = true,
    done: Boolean = false,
    status: SbRowStatus? = null,
    value: String? = null,
    menu: List<SbMenuItem>? = null,
    menuDanger: SbMenuItem? = null,
    menuExpanded: Boolean? = null,
    onMenuExpandedChange: (Boolean) -> Unit = {},
    enabled: Boolean = true,
    menuFocusRequester: FocusRequester? = null,
) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val m = sbMessages()
    val interaction = remember { MutableInteractionSource() }
    val pressed by interaction.collectIsPressedAsState()
    val hovered by interaction.collectIsHoveredAsState()
    val tabular = ty.caption.copy(fontFeatureSettings = ty.numeric.fontFeatureSettings)
    val minHeight = when {
        done && onClick != null -> t.size.controlMd   // 48 dp: a target (spec/02 §3.3)
        done -> t.space.s10                 // 40 dp
        text != null -> 88.dp               // three lines (spec/02 §3.3; no size token)
        meta != null -> t.space.s16         // 64 dp
        else -> t.size.controlLg            // 56 dp
    }
    val fill = when {
        !enabled || onClick == null -> Color.Transparent
        pressed -> c.pressedFill
        hovered -> c.hoverFill
        else -> Color.Transparent
    }
    val line = hairline && !done && fill == Color.Transparent
    val target = if (onClick == null) {
        Modifier
    } else {
        Modifier
            .sbFocusRingInset(interaction)
            .clickable(enabled = enabled, interactionSource = interaction, indication = null, role = Role.Button, onClick = onClick)
    }
    val doneGlyph: @Composable () -> Unit = {
        Icon(SebaroIcons.Filled16.Success, contentDescription = null, tint = c.success, modifier = Modifier.size(t.size.iconSm))
    }
    val tintedLead: @Composable () -> Unit = { CompositionLocalProvider(LocalContentColor provides c.textMuted) { lead?.invoke() } }
    val hasMenu = !done && (!menu.isNullOrEmpty() || menuDanger != null)
    // D105 (25): a row with its own menu keeps a disabled overflow key when disabled, never a chevron
    val chevron = onClick != null && !done && !hasMenu
    val shown = status?.takeIf { !done }
    val stateWord = shown?.let { sbStatusWord(it.tone, it.word) }
    val shownValue = value?.takeIf { !done }
    val endPart: @Composable () -> Unit = {
        CompositionLocalProvider(LocalContentColor provides c.textMuted, LocalTextStyle provides tabular) {
            Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(t.space.s1)) {
                // the row says the state itself (stateDescription below), so the status is silent here (§14.4)
                if (shown != null) {
                    SbStatus(shown.tone, Modifier.clearAndSetSemantics { }, word = stateWord, glyph = shown.glyph)
                }
                if (shownValue != null) {
                    Text(
                        shownValue,
                        style = ty.bodyStrong.copy(fontFeatureSettings = ty.numeric.fontFeatureSettings),
                        color = if (enabled) c.text else c.textMuted,
                        softWrap = false,
                    )
                }
                trail?.invoke(this)
                if (hasMenu) {
                    val menuTarget = menuFocusRequester?.let { Modifier.focusProperties { canFocus = true }.focusRequester(it) } ?: Modifier
                    if (!enabled) {
                        SbIconButton(SebaroIcons.Outline.MoreVertical, m.rowMore(title.text), {}, enabled = false)
                    } else if (menuExpanded != null) {
                        SbOverflowMenu(
                            menu.orEmpty(),
                            menuExpanded,
                            onMenuExpandedChange,
                            modifier = menuTarget,
                            danger = menuDanger,
                            contentDescription = m.rowMore(title.text),
                        )
                    } else {
                        SbOverflowMenu(menu.orEmpty(), modifier = menuTarget, danger = menuDanger, contentDescription = m.rowMore(title.text))
                    }
                }
                if (chevron) Icon(SebaroIcons.Outline.ChevronRight, contentDescription = null, tint = if (enabled) c.text else c.textMuted, modifier = Modifier.size(t.size.iconLg))
            }
        }
    }
    SbEndPartRow(
        modifier
            .fillMaxWidth()
            .semantics { if (!enabled) disabled() }
            .heightIn(min = minHeight)
            .background(fill)
            .drawBehind {
                if (line) {
                    val w = t.borderWidth.hairline.toPx()
                    val inset = t.spacing.gutter.toPx()
                    val rtl = layoutDirection == LayoutDirection.Rtl
                    drawLine(
                        c.border,
                        Offset(if (rtl) 0f else inset, w / 2f),
                        Offset(if (rtl) size.width - inset else size.width, w / 2f),
                        w,
                    )
                }
            }
            .then(if (stateWord != null) Modifier.semantics(mergeDescendants = true) { stateDescription = stateWord } else Modifier)
            .then(target)
            // a done row: 4 dp, or 8 dp as every row when it is a target (spec/02 §3.3); the menu button brings its own room
            .padding(
                start = t.spacing.gutter,
                end = if (hasMenu) t.space.s1 else t.spacing.gutter,
                top = if (done && onClick == null) t.space.s1 else t.space.s2,
                bottom = if (done && onClick == null) t.space.s1 else t.space.s2,
            ),
        gap = t.space.s3,
        stackGap = t.space.s1,
        minMain = with(LocalDensity.current) { ty.body.fontSize.toDp() * 6 },   // 6 × the drawn size (Android scales large sp less)
        lead = if (done) doneGlyph else if (lead != null) tintedLead else null,
        main = { Column {
            if (done) {
                SbWrapText(
                    title,
                    ty.caption,
                    c.textMuted,
                    Modifier.semantics { contentDescription = m.donePrefix + title.text },
                )
            } else {
                // §14.4: words wrap whole at large text, only an overlong word is hyphenated
                SbWrapText(title, ty.body, if (enabled) c.text else c.textMuted)
                if (meta != null) SbWrapText(meta, tabular, c.textMuted)
                if (text != null) SbWrapText(text, tabular, if (enabled) c.text else c.textMuted)
            }
        } },
        end = if (trail != null || chevron || shown != null || shownValue != null || hasMenu) endPart else null,
    )
}

