/**
 * A row of [lead], [main] and [end] (D102 lane narrow, OR-20; provisional, agent): while [main] keeps at least
 * [minMain] (6 × the body size: about six characters) beside the others, they stand in one line, centred vertically
 * as a Row; else [end] goes under [main], start-aligned with it, [stackGap] below, and [main] takes the width beside
 * [lead]. At font scale 1.0 a phone row keeps one line; at 2.0 a status, a time or a button goes under the title
 * instead of squeezing it letter by letter (the web's `sb-list` container rule, spec/02 §3.3).
 */
@Composable
private fun SbEndPartRow(
    modifier: Modifier,
    gap: Dp,
    stackGap: Dp,
    minMain: Dp,
    lead: (@Composable () -> Unit)?,
    main: @Composable () -> Unit,
    end: (@Composable () -> Unit)?,
) {
    Layout(contents = listOf(lead ?: {}, main, end ?: {}), modifier = modifier) { (leadM, mainM, endM), constraints ->
        val gapPx = gap.roundToPx()
        val loose = constraints.copy(minWidth = 0, minHeight = 0)
        val width = if (constraints.hasBoundedWidth) constraints.maxWidth else constraints.minWidth
        val leadP = leadM.firstOrNull()?.measure(loose)
        val leadW = leadP?.let { it.width + gapPx } ?: 0
        // the end part never gets more than the width beside the lead: stacked, it starts there (a wrapping status
        // with a long word in a done row would otherwise run past the row's end by the lead's width)
        val endLimit = if (constraints.hasBoundedWidth) loose.copy(maxWidth = (width - leadW).coerceAtLeast(0)) else loose
        val endP = endM.firstOrNull()?.measure(endLimit)
        val endW = endP?.let { it.width + gapPx } ?: 0
        val stacked = endP != null && width - leadW - endW < minMain.toPx()
        val mainW = (width - leadW - if (stacked) 0 else endW).coerceAtLeast(0)
        val mainP = mainM.first().measure(loose.copy(minWidth = mainW, maxWidth = mainW))
        val under = stackGap.roundToPx()
        val block = if (stacked) mainP.height + under + endP.height else mainP.height   // stacked implies an end part
        val height = maxOf(block, leadP?.height ?: 0, if (stacked) 0 else endP?.height ?: 0, constraints.minHeight)
        // centred as Alignment.CenterVertically rounds, so a one-line row draws exactly as the Row it replaces
        fun centre(h: Int) = ((height - h) / 2f).roundToInt()
        layout(width, height) {
            leadP?.placeRelative(0, centre(leadP.height))
            val top = centre(block)
            mainP.placeRelative(leadW, top)
            if (endP != null) {
                if (stacked) endP.placeRelative(leadW, top + mainP.height + under)
                else endP.placeRelative(width - endP.width, centre(endP.height))
            }
        }
    }
}

/** Group header (spec/02 §3.3): the word in label, textMuted, and the count at 400, tabular: „Offen 2“, „Erledigt 3“. */
@Composable
fun SbListHeader(label: String, modifier: Modifier = Modifier, count: Int? = null) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    Row(
        modifier
            .fillMaxWidth()
            .padding(start = t.spacing.gutter, end = t.spacing.gutter, top = t.space.s4, bottom = t.space.s1)
            .semantics(mergeDescendants = true) { heading() },
        horizontalArrangement = Arrangement.spacedBy(t.space.s2),
    ) {
        // §14.4: the label takes the room beside the count and wraps, the count stays inside the gutter
        SbWrapText(label, ty.label, c.textMuted, Modifier.weight(1f, fill = false))
        if (count != null) {
            Text(
                sbFormatCount(count),
                style = ty.label.copy(fontWeight = ty.caption.fontWeight, fontFeatureSettings = ty.numeric.fontFeatureSettings),
                color = c.textMuted,
            )
        }
    }
}

/** The closing sentence of a list (spec/02 §3.3): „Mehr steht heute nicht an.“ Lists end. */
@Composable
fun SbListEnd(text: String, modifier: Modifier = Modifier) {
    val t = SebaroTheme.tokens
    Text(
        text,
        style = SebaroTheme.typography.caption,
        color = SebaroTheme.colors.textMuted,
        modifier = modifier.fillMaxWidth().padding(start = t.spacing.gutter, end = t.spacing.gutter, top = t.space.s3),
    )
}
